import pathlib, sys
text = pathlib.Path('docs/learning/index.md').read_text(encoding='utf-8')
problems = []
# Assert the three new topics are reachable and that C06/C07 left the
# future-only table, rather than pinning a topic count that every later
# stage would have to edit.
for link in ['../llm/go-primer.md', '../session/go-primer.md', '../scope/go-primer.md']:
    if link not in text:
        problems.append('missing link ' + link)
if '## 当前可学的' not in text:
    problems.append('no current-topics section')
if '| C06 对话与流 |' not in text and 'C06 对话与流 |' not in text:
    problems.append('C06 is not listed as a current topic')
# The old future-only rows must be gone.
for stale in ['| C06 对话与流 | Go 数据类型与接口', '| C07 事件溯源 | C04、C06']:
    if stale in text:
        problems.append('stale future row ' + stale)
print('learning index: OK' if not problems else 'problems: ' + repr(problems))
sys.exit(1 if problems else 0)

